def classify_referral_tasks(apps, schema_editor):
    """Tasks created from a referral (source_handover set) are Referral
    tasks; every other existing task was created as nursing care and keeps
    the Procedure default. Classified from that link only, never the title.
    completed_by is left blank on old completed tasks: it was never recorded,
    and guessing it from the assignee could name the wrong nurse."""
    Task = apps.get_model('api', 'Task')
    Task.objects.filter(source_handover__isnull=False).update(task_type='referral')


